/* Close a job out: records who, when, why and what was still open, then:
   1. ServiceM8: status Completed and moved to the Works completed folder (cbs-enquiry-move action complete). If ServiceM8 is not updated, nothing
      is closed and the page shows its error, so the job is never left half closed. Already Completed = fine (pressing Close out again finishes it).
   2. Hub: closes the job file through cbs-cdm-set (mode closed). Output feeds the cbs_jobs upsert. */
const h=this.helpers,H='https://old-hub.example/webhook/',K='[redacted-internal-key]';
const S=v=>v==null?'':String(v).trim();const jk=v=>S(v).replace(/[^0-9A-Za-z]/g,'').toLowerCase();const num=v=>Number(v)||0;
const b=$input.first().json.body||{};const job=S(b.job).replace(/[^0-9A-Za-z-]/g,''),by=S(b.by).slice(0,80),reason=S(b.reason).slice(0,2000);
if(S(b.a)!=='close')throw new Error('Unknown action.');
if(!job)throw new Error('No job number.');if(!by)throw new Error('Enter your name.');
const open=(Array.isArray(b.open)?b.open:[]).map(x=>S(x).slice(0,240)).filter(Boolean).slice(0,200);
if(open.length&&!reason)throw new Error('Give a reason for closing with items still open.');
const now=new Date().toLocaleString('sv-SE',{timeZone:'Europe/London'}).replace(' ','T').slice(0,16);
const L=await h.httpRequest({method:'POST',url:H+'cbs-admin-save?a=list&t=jobrows&k='+K,body:{},json:true,timeout:30000});
const jr=(Array.isArray(L)?L:[]).filter(r=>r&&jk(r.ref)===jk(job)).sort((x,y)=>num(y.id)-num(x.id))[0]||{};
let old={};try{old=JSON.parse(S(jr.closeout_json)||'{}')||{};}catch(e){old={};}
let sm=null;try{sm=await h.httpRequest({method:'POST',url:H+'cbs-enquiry-move',body:{job:job,action:'complete',note:reason,by:by},json:true,timeout:60000});}catch(e){sm={ok:false,error:'ServiceM8 could not be reached'};}
if(!sm||sm.ok!==true)throw new Error('ServiceM8 was not updated ('+S(sm&&sm.error||'no answer')+'). Nothing was closed. Try again.');
const co=Object.assign({},old,{closed_at:now,by:by,reason:reason,open:open,open_count:open.length,was_mode:S(jr.mode),sm8_completed:now});
co.log=(Array.isArray(old.log)?old.log:[]).concat([{at:now,by:by,ev:'Closed out (ServiceM8 set to Completed, Works completed folder)',reason:reason,open:open.length}]).slice(-20);
await h.httpRequest({method:'POST',url:H+'cbs-cdm-set',body:{job_no:job,mode:'closed',by:by},json:true,timeout:30000});
return [{json:{ref:job,closeout_json:JSON.stringify(co)}}];

